    "ds-graph": {
      "c": "#include <stdbool.h>\n#include <stdio.h>\n#define V 5\n\nint main(void) {\n    // A=0, B=1, C=2, D=3, E=4. -1 marks an unused slot.\n    const int graph[V][3] = {\n        {1, 2, -1}, {0, 3, -1}, {0, 3, 4},\n        {1, 2, 4}, {2, 3, -1}\n    };\n    int queue[V], front = 0, back = 0;\n    bool seen[V] = {false};\n    seen[0] = true;\n    queue[back++] = 0;\n\n    while (front < back) {\n        int node = queue[front++];\n        printf(\"%c\\n\", 'A' + node);\n        for (int i = 0; i < 3 && graph[node][i] != -1; ++i) {\n            int neighbor = graph[node][i];\n            if (!seen[neighbor]) {\n                // Mark on enqueue: each node enters the queue once.\n                seen[neighbor] = true;\n                queue[back++] = neighbor;\n            }\n        }\n    }\n    return 0;\n}",
      "cpp": "#include <iostream>\n#include <map>\n#include <queue>\n#include <set>\n#include <vector>\nint main() {\n    const std::map<char, std::vector<char>> graph{\n        {'A', {'B','C'}}, {'B', {'A','D'}},\n        {'C', {'A','D','E'}}, {'D', {'B','C','E'}},\n        {'E', {'C','D'}}\n    };\n    std::queue<char> q;\n    std::set<char> seen{'A'};\n    q.push('A');\n    while (!q.empty()) {\n        char node = q.front(); q.pop();\n        std::cout << node << '\\n';\n        for (char next : graph.at(node))\n            if (seen.insert(next).second) q.push(next);\n    }\n    // std::map and std::set add logarithmic lookup costs.\n}",
      "python": "from collections import deque\n\ngraph = {\"A\": [\"B\", \"C\"], \"B\": [\"A\", \"D\"],\n         \"C\": [\"A\", \"D\", \"E\"],\n         \"D\": [\"B\", \"C\", \"E\"], \"E\": [\"C\", \"D\"]}\nqueue, seen = deque([\"A\"]), {\"A\"}\nwhile queue:\n    node = queue.popleft()\n    print(node)\n    for neighbor in graph[node]:\n        if neighbor not in seen:\n            seen.add(neighbor)\n            queue.append(neighbor)",
      "java": "import java.util.ArrayDeque;\nimport java.util.Queue;\npublic class Main {\n    public static void main(String[] args) {\n        int[][] graph = {{1,2}, {0,3}, {0,3,4}, {1,2,4}, {2,3}};\n        boolean[] seen = new boolean[5];\n        Queue<Integer> queue = new ArrayDeque<>();\n        seen[0] = true; queue.add(0);\n        while (!queue.isEmpty()) {\n            int node = queue.remove();\n            System.out.println((char)('A' + node));\n            for (int next : graph[node]) {\n                if (!seen[next]) { seen[next]=true; queue.add(next); }\n            }\n        }\n    }\n}",
      "javascript": "const graph = {\n  A: [\"B\", \"C\"], B: [\"A\", \"D\"], C: [\"A\", \"D\", \"E\"],\n  D: [\"B\", \"C\", \"E\"], E: [\"C\", \"D\"]\n};\nconst queue = [\"A\"], seen = new Set([\"A\"]);\n// Advance an index instead of using Array.shift().\nfor (let front = 0; front < queue.length; front++) {\n  const node = queue[front];\n  console.log(node);\n  for (const next of graph[node]) {\n    if (!seen.has(next)) {\n      seen.add(next);\n      queue.push(next);\n    }\n  }\n}",
      "csharp": "using System;\nusing System.Collections.Generic;\nclass Program {\n    static void Main() {\n        int[][] graph = {new[]{1,2},new[]{0,3},new[]{0,3,4},new[]{1,2,4},new[]{2,3}};\n        bool[] seen = new bool[5];\n        var queue = new Queue<int>();\n        seen[0]=true; queue.Enqueue(0);\n        while(queue.Count>0) {\n            int node=queue.Dequeue();\n            Console.WriteLine((char)('A'+node));\n            foreach(int next in graph[node]) {\n                if(!seen[next]) { seen[next]=true; queue.Enqueue(next); }\n            }\n        }\n    }\n}"
    },
    "ds-hash": {
      "c": "#include <stdbool.h>\n#include <stdio.h>\n#include <string.h>\n#define BUCKETS 5\n#define MAX_ENTRIES 10\n\ntypedef struct Entry {\n    const char *key;\n    int value;\n    struct Entry *next;\n} Entry;\n\ntypedef struct {\n    Entry *buckets[BUCKETS];\n    Entry entries[MAX_ENTRIES];\n    size_t used;\n} Table;\n\nunsigned hash(const char *key) {\n    unsigned result = 0;\n    while (*key != '\\0')\n        result = (result + (unsigned char)*key++) % BUCKETS;\n    return result;\n}\n\nEntry *find(Table *t, const char *key) {\n    for (Entry *e = t->buckets[hash(key)]; e != NULL; e = e->next)\n        if (strcmp(e->key, key) == 0) return e;\n    return NULL;\n}\n\nbool put(Table *t, const char *key, int value) {\n    Entry *existing = find(t, key);\n    if (existing != NULL) {\n        existing->value = value;\n        return true;\n    }\n    if (t->used == MAX_ENTRIES) return false;\n    unsigned bucket = hash(key);\n    Entry *e = &t->entries[t->used++];\n    // Keys must outlive the table; literals do in this example.\n    *e = (Entry){key, value, t->buckets[bucket]};\n    t->buckets[bucket] = e;\n    return true;\n}\n\nint main(void) {\n    Table table = {0};\n    if (!put(&table, \"Bo\", 24) || !put(&table, \"Ada\", 25)) return 1;\n    printf(\"Bo: %u, Ada: %u\\n\", hash(\"Bo\"), hash(\"Ada\"));\n    // Both keys have bucket 2 and remain in the chain.\n    for (Entry *e = table.buckets[2]; e != NULL; e = e->next)\n        printf(\"%s: %d\\n\", e->key, e->value);\n    return 0;\n}",
      "cpp": "#include <iostream>\n#include <string>\n#include <unordered_map>\nint main() {\n    std::unordered_map<std::string, int> ages;\n    ages[\"Bo\"] = 24;\n    ages[\"Ada\"] = 25;\n    ages[\"Bo\"] = 26;  // Update this key only.\n    for (const std::string key : {\"Bo\", \"Ada\"}) {\n        auto it = ages.find(key);\n        if (it != ages.end())\n            std::cout << it->first << \": \" << it->second << '\\n';\n    }\n    // Library hashing differs from the animation's teaching hash.\n}",
      "python": "student = {\n    \"name\": \"Ali\",\n    \"age\": 22,\n    \"city\": \"Roskilde\",\n}\n\nprint(student[\"name\"])  # Ali\nstudent[\"age\"] = 23     # Update\n\n# A simple teaching hash (not the internal dict hash):\ndef demo_hash(key):\n    return sum(ord(c) for c in key) % 5",
      "java": "import java.util.HashMap;\nimport java.util.Map;\npublic class Main {\n    public static void main(String[] args) {\n        Map<String,Integer> ages = new HashMap<>();\n        ages.put(\"Bo\",24); ages.put(\"Ada\",25); ages.put(\"Bo\",26);\n        for (String key : new String[]{\"Bo\",\"Ada\"}) {\n            if (ages.containsKey(key)) System.out.println(key + \": \" + ages.get(key));\n        }\n        // HashMap uses a different hash than the visual teaching model.\n    }\n}",
      "javascript": "// Explicit bucket chains demonstrate collisions.\nconst buckets = Array.from({length: 5}, () => []);\nfunction hash(key) {\n  return [...key].reduce((sum, c) => sum + c.codePointAt(0), 0) % 5;\n}\nfunction put(key, value) {\n  const bucket = buckets[hash(key)];\n  const entry = bucket.find(pair => pair[0] === key);\n  if (entry) entry[1] = value;\n  else bucket.push([key, value]);\n}\nput(\"Bo\", 24);\nput(\"Ada\", 25);\nput(\"Bo\", 26);\nfor (const [key, value] of buckets[2]) console.log(`${key}: ${value}`);",
      "csharp": "using System;\nusing System.Collections.Generic;\nclass Program {\n    static void Main() {\n        var ages = new Dictionary<string,int>();\n        ages[\"Bo\"]=24; ages[\"Ada\"]=25; ages[\"Bo\"]=26;\n        foreach(string key in new[]{\"Bo\",\"Ada\"}) {\n            int value;\n            if(ages.TryGetValue(key,out value)) Console.WriteLine(key+\": \"+value);\n        }\n        // Dictionary hashing differs from the teaching animation.\n    }\n}"
    },
